html

<div style="
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    padding: 30px;
    border-radius: 12px;
    color: white;
    text-align: center;
    margin-bottom: 20px;
">
    <h1 style="
        font-size: 32px;
        font-weight: bold;
        margin: 0 0 10px 0;
    ">☕ Configurador de Cafeteras Lavazza</h1>

    <p style="
        font-size: 16px;
        margin: 0;
        opacity: 0.9;
    ">Encuentra la máquina perfecta para tu negocio en 5 pasos</p>
</div>

<div style="
    background: #f8f9fa;
    border-left: 4px solid #667eea;
    padding: 15px 20px;
    margin: 20px 0;
    border-radius: 4px;
">
    <p style="
        font-size: 14px;
        color: #495057;
        margin: 0;
    ">
        <strong style="color: #667eea;">Paso 1 de 5</strong> | 
        Selecciona el tipo de negocio
    </p>
</div>
